import static org.junit.jupiter.api.Assertions.assertNull;

public class ParquetFileReaderReadAllPagesTests {

  @Test
  void readAllPagesReturnsAllDataPagesAndTheirValues() throws Exception {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveType.PrimitiveTypeName.INT32)
        .named("id")
        .named("test_schema");

    Path parquetFile = Files.createTempFile("read-all-pages", ".parquet");
    try {
      Files.deleteIfExists(parquetFile);

      Configuration configuration = new Configuration(false);

      try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(
              new org.apache.hadoop.fs.Path(parquetFile.toUri()))
          .withConf(configuration)
          .withType(schema)
          .build()) {
        SimpleGroupFactory groupFactory = new SimpleGroupFactory(schema);
        writer.write(groupFactory.newGroup().append("id", 11));
        writer.write(groupFactory.newGroup().append("id", 22));
        writer.write(groupFactory.newGroup().append("id", 33));
      }

      InputFile inputFile = HadoopInputFile.fromPath(
          new org.apache.hadoop.fs.Path(parquetFile.toUri()), configuration);

      try (ParquetFileReader reader = ParquetFileReader.open(inputFile)) {
        PageReadStore pageStore = reader.readNextRowGroup();
        ColumnDescriptor descriptor = schema.getColumns().get(0);
        PageReader pageReader = pageStore.getPageReader(descriptor);

        assertEquals(3L, pageReader.getTotalValueCount());

        DataPage firstPage = pageReader.readPage();
        assertNotNull(firstPage);
        assertEquals(3, firstPage.getValueCount());
        assertNull(pageReader.readPage());
      }
    } finally {
      Files.deleteIfExists(parquetFile);
    }
  }
}

